52	// brainPath builds the per-fact route base on repoBasePath, the package's
53	// single point where a repo id becomes part of a request target.
54	func brainPath(repoID string) (string, error) {
55		base, err := repoBasePath(repoID)
56		if err != nil {
57			return "", err
58		}
59		return base + "/brain", nil
60	}
61	
62	// UpsertFacts posts one NDJSON batch to the idempotent per-fact upsert. The
63	// caller chunks to the server's batch cap and verifies identities first —
64	// one bad record rejects the whole batch server-side.
65	func (h *HTTPServer) UpsertFacts(ctx context.Context, repoID string, ndjson []byte) (UpsertCounts, error) {
66		base, err := brainPath(repoID)
67		if err != nil {
68			return UpsertCounts{}, err
69		}
70		req, err := h.newRequest(ctx, http.MethodPost, base+"/facts:upsert", bytes.NewReader(ndjson))
71		if err != nil {
72			return UpsertCounts{}, err
73		}
74		req.Header.Set("Content-Type", "application/x-ndjson")
75		resp, err := h.do(req)
76		if err != nil {
77			return UpsertCounts{}, fmt.Errorf("factsync: POST facts:upsert %s: %w", repoID, err)
78		}
79		defer resp.Body.Close()
80		if resp.StatusCode != http.StatusOK {
81			return UpsertCounts{}, fmt.Errorf("factsync: POST facts:upsert %s: unexpected status %s%s", repoID, resp.Status, h.detail(resp))
82		}
83		var counts UpsertCounts
84		if err := httpx.DecodeJSONBody(resp, &counts); err != nil {
85			return UpsertCounts{}, fmt.Errorf("factsync: decode facts:upsert %s: %w", repoID, err)
86		}
87		return counts, nil
88	}
