90	// FactsFeedPage reads one page of the repo-wide delta feed. pageToken ""
91	// starts from the beginning; pageSize is clamped server-side.
92	func (h *HTTPServer) FactsFeedPage(ctx context.Context, repoID, pageToken string, pageSize int) (FeedPage, error) {
93		base, err := brainPath(repoID)
94		if err != nil {
95			return FeedPage{}, err
96		}
97		query := url.Values{}
98		if pageToken != "" {
99			query.Set("pageToken", pageToken)
100		}
101		if pageSize > 0 {
102			query.Set("pageSize", strconv.Itoa(pageSize))
103		}
104		path := base + "/facts"
105		if encoded := query.Encode(); encoded != "" {
106			path += "?" + encoded
107		}
108		req, err := h.newRequest(ctx, http.MethodGet, path, nil)
109		if err != nil {
110			return FeedPage{}, err
111		}
112		resp, err := h.do(req)
113		if err != nil {
114			return FeedPage{}, fmt.Errorf("factsync: GET facts feed %s: %w", repoID, err)
115		}
116		defer resp.Body.Close()
117		switch {
118		case resp.StatusCode == http.StatusOK:
119		case resp.StatusCode == http.StatusBadRequest && pageToken != "":
120			return FeedPage{}, fmt.Errorf("%w%s", ErrInvalidPageToken, h.detail(resp))
121		default:
122			return FeedPage{}, fmt.Errorf("factsync: GET facts feed %s: unexpected status %s%s", repoID, resp.Status, h.detail(resp))
123		}
124		var page FeedPage
125		if err := httpx.DecodeJSONBody(resp, &page); err != nil {
126			return FeedPage{}, fmt.Errorf("factsync: decode facts feed %s: %w", repoID, err)
127		}
128		return page, nil
129	}
