43	func newFactsRetractCommand(opts Options) *cobra.Command {
44		var (
45			branch  string
46			jsonOut bool
47			global  bool
48		)
49		cmd := &cobra.Command{
50			Use:   "retract <fact-id>",
51			Short: "Mark a fact as retracted (no longer true); pruned later by gc",
52			Args:  cobra.ExactArgs(1),
53			RunE: func(cmd *cobra.Command, args []string) error {
54				factID := args[0]
55				var (
56					brainDir       string
57					resolvedBranch string
58					err            error
59				)
60				// A fact that can be written and not retracted is a fact you are
61				// stuck with. Global facts surface in every repository, so being
62				// stuck with a wrong one is worse, not better.
63				if global {
64					if strings.TrimSpace(branch) != "" {
65						return fmt.Errorf("--global and --branch cannot be combined: a global fact is not on a branch")
66					}
67					brainDir, resolvedBranch, err = resolveGlobalFactsTarget(opts.Env)
68				} else {
69					_, brainDir, resolvedBranch, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
70				}
71				if err != nil {
72					return err
73				}
74				now := opts.Now().UTC()
75				changed := false
76				// Seeded with the id so the event is still identifiable if the
77				// record cannot be re-read after the mutation.
78				retracted := factRecord{ID: factID}
79				if err := withBrainWriteLock(brainDir, func() error {
80					facts, err := loadFacts(brainDir, resolvedBranch)
81					if err != nil {
82						return err
83					}
84					found, didChange := retractFact(facts, factID, now)
85					if !found {
86						if global {
87							return fmt.Errorf("no global fact %s", factID)
88						}
89						return fmt.Errorf("no fact %s on %s", factID, resolvedBranch)
90					}
91					changed = didChange
92					if !changed {
93						return nil
94					}
95					// Captured under the lock so the webhook reports the kind and
96					// paths of the fact that was actually retracted, rather than an
97					// id a subscriber would have to look up through an API that only
98					// listens on loopback.
99					if i := indexOfFact(facts, factID); i >= 0 {
100						retracted = facts[i]
101					}
102					if err := writeFacts(brainDir, resolvedBranch, facts); err != nil {
103						return err
104					}
105					return updateFactSourceManifestLocked(brainDir, now)
106				}); err != nil {
107					return err
108				}
109				// Only on a real transition: re-retracting an already-retracted fact
110				// changed nothing, and a subscriber that fired on it would act on
111				// news that is not news.
112				if changed {
113					if global {
114						notifyGlobalFactWebhook(cmd.Context(), cmd.ErrOrStderr(), WebhookFactRetracted, retracted, now)
115					} else {
116						notifyFactWebhook(cmd.Context(), cmd.ErrOrStderr(), opts, WebhookFactRetracted, resolvedBranch, retracted, now)
117					}
118				}
119				if jsonOut {
120					return writeJSON(cmd, map[string]any{"id": factID, "branch": resolvedBranch, "status": factStatusRetracted, "changed": changed})
121				}
122				where := "on " + resolvedBranch
123				if global {
124					where = "globally"
125				}
126				if changed {
127					fmt.Fprintf(cmd.OutOrStdout(), "retracted %s %s (run `facts gc --force` to prune)\n", factID, where)
128				} else {
129					fmt.Fprintf(cmd.OutOrStdout(), "%s %s was already retracted\n", factID, where)
130				}
131				return nil
132			},
133		}
134		cmd.Flags().StringVar(&branch, "branch", "", "Branch the fact belongs to (default: current branch)")
135		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the result as JSON")
136		cmd.Flags().BoolVar(&global, "global", false, "Retract a global fact rather than one of this repository's")
137		return cmd
138	}
