172	// bulkDecisionVerb / targetedDecisionVerb name the `facts proposals` subcommand
173	// that settles a shared proposal the same way the local flags asked for.
174	func bulkDecisionVerb(act factsReviewActions) string {
175		if act.rejectAll {
176			return "reject"
177		}
178		return "apply"
179	}
180	
181	func targetedDecisionVerb(act factsReviewActions) string {
182		if act.reject != "" {
183			return "reject"
184		}
185		return "apply"
186	}
