188	type factsReviewActions struct {
189		apply, reject       string
190		applyAll, rejectAll bool
191		jsonOut             bool
192	}
193	
194	// validate refuses a request that asks for the same proposal to be both applied
195	// and rejected.
196	//
197	// The resolver below tests applyThis before rejectThis, so every contradictory
198	// combination used to settle the apply half, drop the reject half on the floor
199	// and report "resolved 1 proposal(s)" — a user who mistyped which side they
200	// meant was told their decision had landed while the opposite one actually did.
201	// A contradiction is not a preference to break silently; it is a question only
202	// the caller can answer.
203	func (act factsReviewActions) validate() error {
204		switch {
205		case act.applyAll && act.rejectAll:
206			return fmt.Errorf("--apply-all and --reject-all cannot both be set")
207		case act.applyAll && act.reject != "":
208			return fmt.Errorf("--apply-all and --reject %s cannot both be set: --apply-all already settles that proposal", act.reject)
209		case act.rejectAll && act.apply != "":
210			return fmt.Errorf("--reject-all and --apply %s cannot both be set: --reject-all already settles that proposal", act.apply)
211		case act.apply != "" && act.apply == act.reject:
212			return fmt.Errorf("--apply and --reject cannot both name %s", act.apply)
213		}
214		return nil
215	}
