217	func runFactsReview(cmd *cobra.Command, opts Options, brainDir, branch string, act factsReviewActions) error {
218		if err := act.validate(); err != nil {
219			return err
220		}
221		now := opts.Now().UTC()
222	
223		// No resolution requested: list pending proposals.
224		if act.apply == "" && act.reject == "" && !act.applyAll && !act.rejectAll {
225			proposals, err := loadFactProposals(brainDir, branch)
226			if err != nil {
227				return err
228			}
229			facts, err := loadFacts(brainDir, branch)
230			if err != nil {
231				return err
232			}
233			if act.jsonOut {
234				return writeJSON(cmd, map[string]any{"branch": branch, "proposals": proposals})
235			}
236			if len(proposals) == 0 {
237				fmt.Fprintf(cmd.OutOrStdout(), "no pending proposals on %s\n", branch)
238				return nil
239			}
240			for _, p := range proposals {
241				fmt.Fprintf(cmd.OutOrStdout(), "%s %s -> %s (confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.Confidence)
242				printProposalContext(cmd, facts, p)
243			}
244			return nil
245		}
246	
247		resolved, remaining, deferred := 0, 0, 0
248		if err := withBrainWriteLock(brainDir, func() error {
249			proposals, err := loadFactProposals(brainDir, branch)
250			if err != nil {
251				return err
252			}
253			facts, err := loadFacts(brainDir, branch)
254			if err != nil {
255				return err
256			}
257			// A proposal that has reached the shared open set must be settled THERE.
258			// Settling it only locally leaves the hosted copy open, so a teammate's
259			// later apply silently overrides this member's decision and the next sync
260			// mirrors their outcome back over it. The local queue also holds distill's
261			// private, never-shared backlog (no ProposedBy) — that stays settleable
262			// here, which is what keeps the single-user flow untouched.
263			shared, err := loadSharedProposalLedger(brainDir, branch)
264			if err != nil {
265				return err
266			}
267			isShared := func(p factProposal) bool {
268				if len(shared) == 0 {
269					return false
270				}
271				_, ok := shared[factsync.ProposalID(p)]
272				return ok
273			}
274			keep := proposals[:0:0]
275			for _, p := range proposals {
276				applyThis := act.applyAll || p.CandidateID == act.apply
277				rejectThis := act.rejectAll || p.CandidateID == act.reject
278				if (applyThis || rejectThis) && isShared(p) {
279					if act.applyAll || act.rejectAll {
280						// Bulk settle: skip the shared ones rather than fail the whole
281						// batch, so the private backlog still clears in one command.
282						fmt.Fprintf(cmd.ErrOrStderr(), "skip shared proposal %s: settle it with 'facts proposals %s %s' so every member sees the same outcome\n",
283							p.CandidateID, bulkDecisionVerb(act), p.CandidateID)
284						deferred++
285						keep = append(keep, p)
286						continue
287					}
288					return fmt.Errorf("proposal %s is shared with the team: settle it with 'facts proposals %s %s' instead, so the hosted queue and every member's facts agree (a local-only decision would be overridden by the next sync)",
289						p.CandidateID, targetedDecisionVerb(act), p.CandidateID)
290				}
291				switch {
292				case applyThis:
293					updated, applyErr := applyProposal(facts, p, now)
294					if applyErr != nil {
295						fmt.Fprintf(cmd.ErrOrStderr(), "skip stale proposal %s: %v\n", p.CandidateID, applyErr)
296						resolved++ // drop the stale proposal
297						continue
298					}
299					facts = updated
300					resolved++
301				case rejectThis:
302					facts = rejectProposal(facts, p)
303					resolved++
304				default:
305					keep = append(keep, p)
306				}
307			}
308			if resolved == 0 {
309				if deferred > 0 {
310					// Everything asked for is shared; the interlock already explained
311					// where to settle it. Not an error — nothing was left unhandled.
312					return nil
313				}
314				return fmt.Errorf("no proposal matched")
315			}
316			if err := writeFacts(brainDir, branch, facts); err != nil {
317				return err
318			}
319			if err := writeFactProposals(brainDir, branch, keep); err != nil {
320				return err
321			}
322			remaining = len(keep)
323			return updateFactSourceManifestLocked(brainDir, now)
324		}); err != nil {
325			return err
326		}
327		if deferred > 0 {
328			fmt.Fprintf(cmd.OutOrStdout(), "resolved %d proposal(s) on %s; %d remaining (%d shared, settle with 'facts proposals')\n", resolved, branch, remaining, deferred)
329		} else {
330			fmt.Fprintf(cmd.OutOrStdout(), "resolved %d proposal(s) on %s; %d remaining\n", resolved, branch, remaining)
331		}
332		return nil
333	}
