395	// factsBranchIsReal reports whether a branch name still names something: a ref
396	// git knows, or a fact store this brain already holds. The second half matters
397	// because a merged feature branch is commonly deleted while its facts live on,
398	// and promoting those forward is the whole point of the command.
399	func factsBranchIsReal(ctx context.Context, opts Options, repoDir, brainDir, branch string) bool {
400		if factBranchStoreExists(brainDir, branch) {
401			return true
402		}
403		return gitRefExists(ctx, opts.Runner, repoDir, "refs/heads/"+branch) ||
404			gitRefExists(ctx, opts.Runner, repoDir, "refs/remotes/origin/"+branch)
405	}
406	
407	// validateFactsPromoteEndpoints checks the two branch names promote was handed.
408	// Neither used to be checked at all, and each typo failed in its own quiet way:
409	//
410	//   - a bad --from loaded nothing (loadFacts reads a missing store as an empty
411	//     branch) and reported "promoted 0 fact(s)" — the same success line a real
412	//     but empty source produces, so the user had no way to tell a typo from a
413	//     branch that genuinely had nothing to give;
414	//   - a bad --into was worse than quiet. writeFacts creates the target store on
415	//     demand, so promote happily forked the fact set into a directory keyed to a
416	//     branch that does not exist. Nothing reads it back, no later command names
417	//     it, and no branch can ever reach it: the facts are gone while the command
418	//     reports success.
419	//
420	// So both endpoints must name something real, and --from must additionally have
421	// facts — "nothing to promote" is a distinct, stateable outcome, not a success.
422	func validateFactsPromoteEndpoints(ctx context.Context, opts Options, repoDir, brainDir, from, into string) error {
423		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, from) {
424			return fmt.Errorf("--from %q is not a branch: git does not know it and this brain holds no facts for it", from)
425		}
426		if !factBranchStoreExists(brainDir, from) {
427			return fmt.Errorf("--from %q has no facts to promote", from)
428		}
429		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, into) {
430			return fmt.Errorf("--into %q is not a branch: git does not know it and this brain holds no facts for it; promoting into it would strand a fact store no branch can reach", into)
431		}
432		return nil
433	}
