435	func runFactsPromote(cmd *cobra.Command, opts Options, brainDir, from, into, strategy string, jsonOut bool) error {
436		now := opts.Now().UTC()
437		var promoted, proposalCount int
438		if err := withBrainWriteLock(brainDir, func() error {
439			source, err := loadFacts(brainDir, from)
440			if err != nil {
441				return err
442			}
443			target, err := loadFacts(brainDir, into)
444			if err != nil {
445				return err
446			}
447			merged, proposals, promotedCount := promoteFacts(source, target, strategy, into, now)
448			promoted = promotedCount
449			proposalCount = len(proposals)
450			if err := writeFacts(brainDir, into, merged); err != nil {
451				return err
452			}
453			if len(proposals) > 0 {
454				existing, _ := loadFactProposals(brainDir, into)
455				if err := writeFactProposals(brainDir, into, dedupeProposals(append(existing, proposals...))); err != nil {
456					return err
457				}
458			}
459			return updateFactSourceManifestLocked(brainDir, now)
460		}); err != nil {
461			return err
462		}
463		summary := map[string]any{"from": from, "into": into, "strategy": strategy, "promoted": promoted, "proposals": proposalCount}
464		if jsonOut {
465			return writeJSON(cmd, summary)
466		}
467		fmt.Fprintf(cmd.OutOrStdout(), "promoted %d fact(s) from %s into %s (%s); %d conflict(s) queued for review\n", promoted, from, into, strategy, proposalCount)
468		return nil
469	}
