542	func runFactsReclassify(cmd *cobra.Command, opts Options, brainDir, branch string, force, jsonOut bool) error {
543		now := opts.Now().UTC()
544		var facts []factRecord
545		changed := 0
546		// The whole load-mutate-write runs under the brain write lock, like every
547		// other fact mutator (remember, retract, review, promote, gc, distill's
548		// flush) and like the refresh-time reclassifyAllFactBranches. Reading the
549		// store outside it and writing the mutated copy back is a lost update: a
550		// concurrent writer that commits between this read and this write is
551		// silently overwritten, and its facts disappear.
552		if err := withBrainWriteLock(brainDir, func() error {
553			loaded, err := loadFacts(brainDir, branch)
554			if err != nil {
555				return err
556			}
557			facts = loaded
558			changed = reclassifyFacts(facts, force)
559			if changed > 0 {
560				if err := writeFacts(brainDir, branch, facts); err != nil {
561					return err
562				}
563			}
564			// Always refresh the manifest, even on a no-op reclassify: a store predating
565			// the by_kind field has valid kinds but a stale/absent histogram that only a
566			// manifest rebuild repairs.
567			return updateFactSourceManifestLocked(brainDir, now)
568		}); err != nil {
569			return err
570		}
571		byKind := map[string]int{}
572		for _, f := range facts {
573			if f.Status == factStatusActive {
574				byKind[factKindOrInferred(f)]++
575			}
576		}
577		if jsonOut {
578			return writeJSON(cmd, map[string]any{"branch": branch, "changed": changed, "facts": len(facts), "by_kind": byKind})
579		}
580		fmt.Fprintf(cmd.OutOrStdout(), "reclassified %d of %d fact(s) on %s\n", changed, len(facts), branch)
581		for _, kind := range []string{factKindDecision, factKindInvariant, factKindGotcha, factKindPreference, factKindConvention} {
582			if byKind[kind] > 0 {
583				fmt.Fprintf(cmd.OutOrStdout(), "  %-11s %d\n", kind, byKind[kind])
584			}
585		}
586		return nil
587	}
