641	func newFactsMapCommand(opts Options) *cobra.Command {
642		var (
643			branch  string
644			path    string
645			depth   int
646			jsonOut bool
647		)
648		cmd := &cobra.Command{
649			Use:   "map",
650			Short: "Render the synthesized fact outline (summaries + structure) with progressive disclosure",
651			Args:  cobra.NoArgs,
652			RunE: func(cmd *cobra.Command, args []string) error {
653				_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
654				if err != nil {
655					return err
656				}
657				// Always rebuild the structure from the live facts (it is deterministic
658				// and never stale), then overlay stored summaries only where the node's
659				// fingerprint still matches — so a summary for a changed subtree is
660				// hidden rather than shown stale, and no `facts outline` run is required
661				// to see the map.
662				facts, err := loadFacts(brainDir, resolvedBranch)
663				if err != nil {
664					return err
665				}
666				outline := buildFactOutlineTree(resolvedBranch, facts, opts.Now().UTC())
667				if stored, storedErr := loadFactOutline(brainDir, resolvedBranch); storedErr == nil {
668					for key, n := range outline.Nodes {
669						if s, ok := stored.Nodes[key]; ok && s.Fingerprint == n.Fingerprint && s.Summary != "" {
670							n.Summary = s.Summary
671							outline.Nodes[key] = n
672						}
673					}
674				}
675				node := path
676				if _, ok := outline.Nodes[node]; !ok {
677					return fmt.Errorf("no outline node %q on %s", path, resolvedBranch)
678				}
679				// The outline counts what loadFacts produced. When the manifest
680				// declares more than that, "root (4 facts)" is a count of survivors
681				// rendered as if it were the corpus. Qualify it before rendering,
682				// and exit nonzero so a caller cannot read the map as complete.
683				integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
684				if jsonOut {
685					if err := writeJSON(cmd, outline); err != nil {
686						return err
687					}
688					return integrityErr
689				}
690				var b strings.Builder
691				renderFactOutline(&b, outline, node, depth)
692				if b.Len() == 0 {
693					fmt.Fprintf(cmd.OutOrStdout(), "no facts on %s\n", resolvedBranch)
694					return integrityErr
695				}
696				fmt.Fprint(cmd.OutOrStdout(), b.String())
697				return integrityErr
698			},
699		}
700		cmd.Flags().StringVar(&branch, "branch", "", "Branch to map (default: current branch)")
701		cmd.Flags().StringVar(&path, "path", "", "Drill into a node key (a directory tier, e.g. internal/cli)")
702		cmd.Flags().IntVar(&depth, "depth", 0, "Levels to render below the node (0 = all)")
703		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline as JSON")
704		return cmd
705	}
