707	func runFactsGC(cmd *cobra.Command, opts Options, brainDir, branch string, force bool, retain time.Duration, jsonOut bool) error {
708		facts, err := loadFacts(brainDir, branch)
709		if err != nil {
710			return err
711		}
712		now := opts.Now().UTC()
713		taxonomy, err := loadFactTaxonomy(brainDir, now)
714		if err != nil {
715			return err
716		}
717		result := gcFacts(facts, taxonomy, now, retain)
718	
719		summary := map[string]any{
720			"branch":    branch,
721			"pruned":    len(result.Pruned),
722			"orphans":   len(result.Orphans),
723			"remaining": len(result.Kept),
724			"applied":   force,
725		}
726		if force {
727			if err := withBrainWriteLock(brainDir, func() error {
728				facts, err := loadFacts(brainDir, branch)
729				if err != nil {
730					return err
731				}
732				taxonomy, err := loadFactTaxonomy(brainDir, now)
733				if err != nil {
734					return err
735				}
736				result = gcFacts(facts, taxonomy, now, retain)
737				summary["pruned"] = len(result.Pruned)
738				summary["orphans"] = len(result.Orphans)
739				summary["remaining"] = len(result.Kept)
740				if err := writeFacts(brainDir, branch, result.Kept); err != nil {
741					return err
742				}
743				return updateFactSourceManifestLocked(brainDir, now)
744			}); err != nil {
745				return err
746			}
747		}
748		if jsonOut {
749			return writeJSON(cmd, summary)
750		}
751		verb := "would prune"
752		if force {
753			verb = "pruned"
754		}
755		fmt.Fprintf(cmd.OutOrStdout(), "%s %d fact(s) on %s (%d retracted/old-superseded); %d taxonomy-orphaned fact(s) reported (kept); %d remaining\n",
756			verb, len(result.Pruned), branch, len(result.Pruned), len(result.Orphans), len(result.Kept))
757		if !force && len(result.Pruned) > 0 {
758			fmt.Fprintln(cmd.OutOrStdout(), "re-run with --force to apply")
759		}
760		return nil
761	}
